/* @ACTUAL_NATIVE_ORDER@ */
static const std::vector<std::string> native_order = [] {
    std::vector<std::string> result;
    for (unsigned i = 0; def_cooling_devices[i]; ++i) result.push_back(def_cooling_devices[i]);
    return result;
}();
static void native_trips(cthd_zone &zone) {
    cthd_trip_point passive(0, PASSIVE, 95000, 0, 0, DEFAULT_SENSOR_ID, SEQUENTIAL);
    for (const auto &name : native_order)
        passive.thd_trip_point_add_cdev(*devices.at(name), cthd_trip_point::default_influence);
    zone.add_trip(passive);
    cthd_trip_point active(1, ACTIVE, 90000, 0, 0, DEFAULT_SENSOR_ID, SEQUENTIAL);
    zone.add_trip(active);
}
static bool qualified(cthd_zone &zone) {
    auto &trip = zone.passive();
    if (sensor_errors || trip.get_trip_temp() != 90000 || trip.get_trip_hyst() != 3000
            || trip.get_sensor_id() != 7 || trip.get_cdev_count() != native_order.size()) return false;
    for (unsigned i = 0; i < native_order.size(); ++i) {
        auto &binding = trip.get_cdev_at_index(i);
        if (binding.cdev->get_cdev_type() != native_order[i] || binding.influence != 0
                || binding.sampling_priod != 0 || binding.target_state_valid
                || binding.pid_param.valid || binding.min_max_valid) return false;
    }
    return true;
}

int main(int argc, char **argv) {
    require(argc == 2, "case required");
    const std::string name = argv[1];
    // stdin is a bounded, typed parse of the repository-generated XML. The
    // libxml2 parser is doubled; no hand-authored temperature or binding list
    // replaces the product XML in successful cases.
    int ceiling, floor, influence, sampling;
    unsigned count;
    trip_point_t trip;
    std::string type, control;
    require(bool(std::cin >> ceiling >> floor >> trip.sensor_type >> trip.temperature
                 >> trip.hyst >> type >> control >> count), "invalid XML mapping input");
    require(count <= 32, "unbounded XML mapping");
    require(type == "passive" && control == "SEQUENTIAL", "wrong XML trip/control type");
    for (unsigned i = 0; i < count; ++i) {
        cdev_config config;
        require(bool(std::cin >> config.type >> influence >> sampling), "invalid cooling mapping");
        config.influence = influence; config.sampling_period = sampling;
        trip.cdev_trips.push_back(config);
    }
    int configured_debounce;
    require(bool(std::cin >> configured_debounce), "missing XML debounce mapping");
    require(configured_debounce == -1 || configured_debounce == 0 || configured_debounce == 2,
            "unexpected debounce mapping");
    test_rapl rapl;
    rapl.configure(ceiling, floor);
    // Model the parser/engine parameter setter, not the libxml parse itself.
    if (configured_debounce >= 0) rapl.set_debounce_interval(configured_debounce);
    next_cdev pstate(2, "intel_pstate"), powerclamp(3, "intel_powerclamp"),
              cpufreq(4, "cpufreq"), processor(5, "Processor");
    devices = {{"rapl_controller", &rapl}, {"intel_pstate", &pstate},
               {"intel_powerclamp", &powerclamp}, {"cpufreq", &cpufreq}, {"Processor", &processor}};
    cthd_zone zone;
    native_trips(zone);
    if (name == "missing_cdev") devices.erase("intel_powerclamp");
    std::vector<trip_point_t> trips = {trip};
    const bool activated = apply_actual_xml(&zone, trips);
    require(zone.trip_points.size() == 2, "same-type replacement lost/duplicated other trips");
    require(std::any_of(zone.trip_points.begin(), zone.trip_points.end(), [](auto &t) {
        return t.get_trip_type() == ACTIVE && t.get_trip_temp() == 90000;
    }), "ACTIVE trip lost");
    if (name == "invalid_sensor") {
        require(sensor_errors == 1 && !activated, "invalid sensor incorrectly activated XML");
        require(zone.passive().get_sensor_id() == DEFAULT_SENSOR_ID,
                "invalid sensor replaced original binding identity");
        require(zone.passive().get_cdev_count() == 5, "fallback lost original bindings");
        require(!qualified(zone), "invalid sensor was falsely qualified");
        return 0;
    }
    if (name == "missing_cdev") {
        require(activated && zone.passive().get_cdev_count() == 4, "missing cdev handling changed");
        require(!qualified(zone), "missing cooling device was falsely qualified");
        return 0;
    }
    if (name == "zero_temperature") {
        require(!activated && zone.passive().get_trip_temp() == 95000,
                "out-of-scope zero-temperature XML unexpectedly replaced native trip");
        require(!qualified(zone), "zero-temperature XML was falsely qualified");
        return 0;
    }
    // This common gate is intentionally also used by mutated XML tests: an
    // old95 or dropped-binding regression must fail before hardware semantics.
    require(activated && qualified(zone), "target90 native binding qualification failed");
    auto &passive = zone.passive();
    bool reset = false;
    require(!passive.thd_trip_point_check(8, 92000, PREF_ENERGY_CONSERVE, &reset),
            "wrong sensor unexpectedly triggered passive trip");
    require(rapl.get_curr_state() == ceiling && pstate.writes == 0,
            "wrong sensor changed cooling devices");
    require(passive.thd_trip_point_check(7, 89000, PREF_ENERGY_CONSERVE, &reset),
            "matching sensor failed below threshold");
    require(rapl.get_curr_state() == ceiling && pstate.writes == 0,
            "below-target reading activated cooling");
    const bool cadence_case = name == "debounce_default" || name == "debounce_zero";
    const int interval = cadence_case ? 1 : 3;
    const int expected_debounce = name == "debounce_zero" ? 0 : 2;
    if (cadence_case)
        require(rapl.debounce_seconds() == expected_debounce,
                "XML debounce did not select intended native controller parameter");
    std::vector<time_t> actions;
    for (int i = 0; i < 40 && !rapl.in_max_state(); ++i) {
        const int before = rapl.get_curr_state();
        require(passive.thd_trip_point_check(7, 92000, PREF_ENERGY_CONSERVE, &reset),
                "matching sensor rejected hot reading");
        const int after = rapl.get_curr_state();
        require(after >= floor && after <= ceiling, "RAPL state exceeded paired range");
        if (after != before) actions.push_back(fixture_seconds);
        if (cadence_case && !rapl.in_max_state()) {
            require(passive.thd_trip_point_check(7, 92000, PREF_ENERGY_CONSERVE, &reset),
                    "same-second hot observation rejected");
            require(rapl.get_curr_state() == after,
                    "native debounce failed to suppress repeat action in same second");
        }
        require(pstate.writes == 0, "SEQUENTIAL activated next device before RAPL floor");
        fixture_seconds += interval;
    }
    require(actions.size() >= 3, "insufficient native controller actions to prove cadence");
    if (cadence_case) {
        for (unsigned i = 1; i < actions.size(); ++i)
            require(actions[i] - actions[i-1] == expected_debounce + 1,
                    "native debounce cadence differs from expected one-second observations");
        std::cout << "RAPL action seconds:";
        for (auto second : actions) std::cout << ' ' << second;
        std::cout << '\n';
    }
    require(rapl.in_max_state() && rapl.get_curr_state() == floor,
            "actual RAPL did not reach paired floor");
    require(pstate.writes == 0, "SEQUENTIAL activated next device before RAPL floor");
    require(passive.thd_trip_point_check(7, 92000, PREF_ENERGY_CONSERVE, &reset),
            "sequential escalation rejected");
    require(pstate.writes == 1 && pstate.get_curr_state() > 0,
            "actual trip did not escalate to native intel_pstate");
    require(powerclamp.writes == 0 && cpufreq.writes == 0 && processor.writes == 0,
            "SEQUENTIAL activated later devices too early");
    // Within the 3C hysteresis band, neither 89C nor exactly 87C may release.
    const int held_pstate = pstate.get_curr_state();
    const auto held_rapl_writes = rapl.hardware().writes.size();
    const int held_pstate_writes = pstate.writes;
    for (const auto reading : {89000, 87000}) {
        fixture_seconds += 3;
        require(passive.thd_trip_point_check(7, reading, PREF_ENERGY_CONSERVE, &reset),
                "hysteresis-band observation rejected");
        require(rapl.get_curr_state() == floor && pstate.get_curr_state() == held_pstate
                && rapl.hardware().writes.size() == held_rapl_writes
                && pstate.writes == held_pstate_writes,
                "cooling released inside hysteresis band or at exact boundary");
    }
    // Below 87C, release the most recently active device first, then RAPL.
    // The native RAPL release must restore the configured ceiling, never the
    // unqualified 140 W power-on value retained by the sysfs double.
    for (int i = 0; i < 40 && (pstate.get_curr_state() || rapl.get_curr_state() != ceiling); ++i) {
        fixture_seconds += 1;
        require(passive.thd_trip_point_check(7, 86999, PREF_ENERGY_CONSERVE, &reset),
                "cool reading failed to release native cooling");
        require(rapl.get_curr_state() >= floor && rapl.get_curr_state() <= ceiling,
                "release escaped configured RAPL range");
    }
    require(pstate.get_curr_state() == 0 && rapl.get_curr_state() == ceiling,
            "native cooling did not fully recover after temperature fell");
    for (const auto &write : rapl.hardware().writes)
        if (write.key == "constraint_0_power_limit_uw" && write.status > 0)
            require(write.value >= floor && write.value <= ceiling,
                    "actual RAPL sysfs write exceeded qualified range");
    return 0;
}
